<?php $newsCategory = bl_query('category'); $articles = array_values(array_filter(bl_articles(), static fn($a) => !$newsCategory || $a['category'] === $newsCategory)); ?>
<section class="bl-page-hero bl-shell"><?php bl_breadcrumbs([['label' => 'News']]); ?><div class="bl-page-heading"><div><p class="bl-eyebrow">COMPANY / PEOPLE / CONNECTIONS</p><h1>INSIDE<br><span class="bl-blue-text">BOB-LIFT.</span></h1></div><p>Stories from the company behind your equipment. Published updates, with a connection to the original source.</p></div></section>
<section class="bl-journal bl-shell"><nav class="bl-category-nav" aria-label="News categories"><?php foreach (['' => 'All stories', 'Company news' => 'Company news', 'Exhibitions' => 'Exhibitions'] as $value => $label): ?><a href="<?= bl_escape(bl_url('/news/') . ($value ? '?category=' . rawurlencode($value) : '')) ?>" <?= $value === $newsCategory ? 'aria-current="page"' : '' ?>><?= $label ?></a><?php endforeach; ?></nav><?php if ($articles): ?><div class="bl-news-grid"><?php foreach ($articles as $article) bl_news_card($article); ?></div><?php else: ?><div class="bl-empty"><h2>No stories in this category.</h2><a href="<?= bl_escape(bl_url('/news/')) ?>" class="bl-text-link">View all stories <?= bl_icon('arrow-up-right') ?></a></div><?php endif; ?></section>
